const aiOutput = $json.output[0].content[0].text;

const resumeScores = aiOutput.scores;
const jobMatch = aiOutput.job_match;

// Resume overall score
const overallScore = Math.round(
  (
    resumeScores.summary * 0.10 +
    resumeScores.experience * 0.25 +
    resumeScores.skills * 0.15 +
    resumeScores.projects * 0.15 +
    resumeScores.education * 0.10 +
    resumeScores.formatting * 0.10 +
    resumeScores.ats * 0.15
  ) * 10
);

// ATS score
const atsScore = resumeScores.ats * 10;

// Job match score
const jobMatchScore = Math.round(
  (
    jobMatch.scores.skills * 0.35 +
    jobMatch.scores.experience * 0.30 +
    jobMatch.scores.keywords * 0.20 +
    jobMatch.scores.projects * 0.15
  ) * 10
);

return [
  {
    json: {
      candidate_name: aiOutput.candidate_name,

      overall_score: overallScore,

      ats_score: atsScore,

      score_breakdown: {
        summary: resumeScores.summary,
        experience: resumeScores.experience,
        skills: resumeScores.skills,
        projects: resumeScores.projects,
        education: resumeScores.education,
        formatting: resumeScores.formatting,
        ats: resumeScores.ats
      },

      skills: aiOutput.skills,

      strengths: aiOutput.strengths,

      weaknesses: aiOutput.weaknesses,

      recommendations: aiOutput.recommendations,

      job_match: {
        match_score: jobMatchScore,

        score_breakdown: {
          skills: jobMatch.scores.skills,
          experience: jobMatch.scores.experience,
          keywords: jobMatch.scores.keywords,
          projects: jobMatch.scores.projects
        },

        required_skills: jobMatch.required_skills,

        preferred_skills: jobMatch.preferred_skills,

        matched_skills: jobMatch.matched_skills,

        missing_required_skills: jobMatch.missing_required_skills,

        missing_preferred_skills: jobMatch.missing_preferred_skills,

        matched_keywords: jobMatch.matched_keywords,

        missing_keywords: jobMatch.missing_keywords,

        recommendations: jobMatch.recommendations
      }
    }
  }
];

const data = $json;

const technicalSkills = data.skills.technical
  .map(skill => `<span class="tag">${skill}</span>`)
  .join("");

const softSkills = data.skills.soft
  .map(skill => `<span class="tag">${skill}</span>`)
  .join("");

const strengths = data.strengths
  .map(item => `<li>${item}</li>`)
  .join("");

const weaknesses = data.weaknesses
  .map(item => `<li>${item}</li>`)
  .join("");

const recommendations = data.recommendations
  .map(item => `<li>${item}</li>`)
  .join("");

const requiredSkills = data.job_match.required_skills
  .map(skill => `<span class="tag">${skill}</span>`)
  .join("");

const preferredSkills = data.job_match.preferred_skills
  .map(skill => `<span class="tag">${skill}</span>`)
  .join("");

const missingRequiredSkills = data.job_match.missing_required_skills
  .map(skill => `<span class="tag missing">${skill}</span>`)
  .join("");

const missingPreferredSkills = data.job_match.missing_preferred_skills
  .map(skill => `<span class="tag missing">${skill}</span>`)
  .join("");

const matchedSkills = data.job_match.matched_skills
  .map(skill => `<span class="tag matched">${skill}</span>`)
  .join("");

const matchedKeywords = data.job_match.matched_keywords
  .map(keyword => `<span class="tag matched">${keyword}</span>`)
  .join("");

const missingKeywords = data.job_match.missing_keywords
  .map(keyword => `<span class="tag missing">${keyword}</span>`)
  .join("");

const jobRecommendations = data.job_match.recommendations
  .map(item => `<li>${item}</li>`)
  .join("");

